module external_hermite
    implicit none
    public :: hermite

contains
    FUNCTION hermite(npt, func, ier) RESULT(fn_val)
        !! Author: Alan Miller
        !!
        !! Original Source: https://wp.csiro.au/alanmiller/hermite.f90
        !! Used with Alan Miller's permission
        !!
        !!       HERMITE INTEGRATION, I.E. EVALUATION OF THE INTEGRAL OF
        !!       exp(-x**2)*f(x) FROM -INFINITY TO +INFINITY
        !!
        !!       NPT     = INPUT, NO. OF POINTS AT WHICH f(x) IS TO BE EVALUATED.
        !!                 NPT MUST BE ONE OF 2, 4, 6, 8, 10, 12, 16, 20.
        !!       FUNC    = INPUT, NAME OF THE USER'S FUNCTION TO SUPPLY VALUES
        !!                 OF F(X).   THE FUNCTION MAY HAVE ANY NAME BUT ONLY THE
        !!                 ONE ARGUMENT, X.
        !!       IER     = OUTPUT, ERROR INDICATOR
        !!                   = 0 NO ERROR DETECTED
        !!                   = 1 ILLEGAL VALUE OF NPT
        !!
        !!       LATEST REVISION - 5 December 1999
        ! ************************************************************************

        IMPLICIT NONE
        INTEGER, PARAMETER :: dp = SELECTED_REAL_KIND(12, 60)

        INTEGER, INTENT(IN)  :: npt
        INTEGER, INTENT(OUT) :: ier
        REAL (dp)            :: fn_val

        INTERFACE
            FUNCTION func(x) RESULT(fn_val)
                IMPLICIT NONE
                INTEGER, PARAMETER    :: dp = SELECTED_REAL_KIND(12, 60)
                REAL (dp), INTENT(IN) :: x
                REAL (dp)             :: fn_val
            END FUNCTION func
        END INTERFACE

        !     Local variables

        REAL (dp) :: xpt(89) = (/ 0.707106781186548_dp, &
            0.524647623275290_dp, 1.650680123885785_dp, &
            0.436077411927617_dp, 1.335849074013697_dp, 2.350604973674492_dp, &
            0.381186990207322_dp, 1.157193712446780_dp, 1.981656756695843_dp, &
            2.930637420257244_dp, &
            0.342901327223705_dp, 1.036610829789514_dp, 1.756683649299882_dp, &
            2.532731674232790_dp, 3.436159118837738_dp, &
            0.314240376254359_dp, 0.947788391240164_dp, 1.597682635152605_dp, &
            2.279507080501060_dp, 3.020637025120890_dp, 3.889724897869782_dp, &
            0.27348104613815_dp,  0.82295144914466_dp, 1.38025853919888_dp, &
            1.95178799091625_dp,  2.54620215784748_dp, 3.17699916197996_dp, &
            3.86944790486012_dp,  4.68873893930582_dp, &
            0.2453407083009_dp,   0.7374737285454_dp, 1.2340762153953_dp, &
            1.7385377121166_dp,   2.2549740020893_dp, 2.7888060584281_dp, &
            3.3478545673832_dp,   3.9447640401156_dp, 4.6036824495507_dp, &
            5.3874808900112_dp, &
            0.11079587242243949,0.3324146923422318,0.554114823591617,&
            0.7759507615401458,0.9979774360981052,1.220250391218953,&
            1.4428259702159327,1.6657615087415094,1.8891155374270083,&
            2.112947996371188,2.3373204639068783,2.562296402372608,&
            2.7879414239819895,3.0143235803311557,3.241513679631013,&
            3.4695856364185893,3.698616859318492,3.928688683427671,&
            4.15988685513103,4.392302078682684,4.6260306357871555,&
            4.86117509179121,5.097845105089136,5.33615836013836,&
            5.5762416493299245,5.818232135203517,6.062278832614303,&
            6.308544361112135,6.557207031921539,6.808463352858796,&
            7.062531060248865,7.319652822304535,7.580100807857489,&
            7.844182384460821,8.112247311162792,8.384696940416266,&
            8.661996168134518,8.944689217325475,9.233420890219161,&
            9.528965823390115,9.832269807777969,10.144509941292846,&
            10.467185421342812,10.802260753684715,11.152404385585125,&
            11.521415400787031,11.915061943114166,12.342964222859674,&
            12.82379974948781,13.406487338144911/), &
            wt(89) = (/ 8.862269254528D-1, &
            8.049140900055D-1, 8.131283544725D-2, &
            7.246295952244D-1, 1.570673203229D-1, 4.530009905509D-3, &
            6.611470125582D-1, 2.078023258149D-1, 1.707798300741D-2, &
            1.996040722114D-4, &
            6.108626337353D-1, 2.401386110823D-1, 3.387439445548D-2, &
            1.343645746781D-3, 7.640432855233D-6, &
            5.701352362625D-1, 2.604923102642D-1, 5.160798561588D-2, &
            3.905390584629D-3, 8.573687043588D-5, 2.658551684356D-7, &
            5.079294790166D-1, 2.806474585285D-1, 8.381004139899D-2, &
            1.288031153551D-2, 9.322840086242D-4, 2.711860092538D-5, &
            2.320980844865D-7, 2.654807474011D-10, &
            4.622436696006D-1, 2.866755053628D-1, 1.090172060200D-1, &
            2.481052088746D-2, 3.243773342238D-3, 2.283386360163D-4, &
            7.802556478532D-6, 1.086069370769D-7, 4.399340992273D-10, &
            2.229393645534D-13, &
            0.21889262958743907,0.19846285025418658,0.16313003050278288,0.12153798684410431,&
            0.08205182739122438,0.05017581267742869,0.027779127385933536,0.0139156652202318,&
            0.006303000285608057,0.0025792732600590914,0.0009526921885486212,0.00031729197104330017,&
            9.517162778550938e-05,2.5676159384548985e-05,6.221524817777863e-06,1.3517971591103664e-06,&
            2.629097483753728e-07,4.568127508484932e-08,7.075857283889625e-09,9.74792125387158e-10,&
            1.1913006349290783e-10,1.2879038257315495e-11,1.2278785144101313e-12,1.0288749373509969e-13,&
            7.548896877915176e-15,4.829835321703059e-16,2.6824921647603564e-17,1.2868329211211485e-18,&
            5.302316183131867e-20,1.8649976751302644e-21,5.561026961659205e-23,1.3948415260687771e-24,&
            2.9173500726293086e-26,5.037791166213166e-28,7.101812226385044e-30,8.067434278709205e-32,&
            7.274572596887653e-34,5.116232604385216e-36,2.7487848843571495e-38,1.1004706827142353e-40,&
            3.185217877835948e-43,6.4207252053484285e-46,8.597563954825298e-49,7.191529463463198e-52,&
            3.459477936475526e-55,8.518883081761247e-59,9.019222303693468e-63,3.083028990003312e-67,&
            1.972860574879364e-72,5.908067865030892e-79 &
            /), zero = 0.0_dp, x
        INTEGER  :: npts(9) = (/ 2, 4, 6, 8, 10, 12, 16, 20, 100/), ipos, i, nby2

        !       CHECK FOR PERMISSIBLE VALUE OF NPT.

        fn_val = zero
        ipos = 1
        DO i = 1, 8
            IF(npts(i).EQ.npt) GO TO 20
            ipos = ipos + (npts(i) + 1)/2
        END DO
        ier = 1
        RETURN

        !       EVALUATE SUM OF WT(I) * FUNC(X(I))

20      nby2 = (npt + 1)/2
        DO i = 1, nby2
            x = xpt(ipos)
            fn_val = fn_val + wt(ipos) * (func(x) + func(-x))
            ipos = ipos + 1
        END DO
        ier = 0
        RETURN

    END FUNCTION hermite

end module external_hermite
